// Assemble the D7 brand guidelines book from the chapter source and the
// deliverable pages, so the book always matches D2, D4, D5, D6 and D1.
// Writes src/pages/D7-guidelines.html (generated; do not edit by hand).
//
// Each source keeps its own <style> (scoped under a wrapper class) and its
// own scripts (wrapped in a function). All of a source's pages are loaded so
// its scripts can run; pages not chosen below are removed afterwards.
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const pages = path.join(root, 'src/pages');

// [source file, page numbers (1-based) or chapter ids, contents title]
const PLAN = [
  ['_book-chapters.html', ['cover', 'contents', 'positioning'], null],
  ['D1-competitive.html', [4], 'Positioning'],
  ['_book-chapters.html', ['voice', 'banned', 'less1', 'less2'], 'Voice and restraint'],
  ['D2-logo-system.html', [2, 3, 4, 5, 6, 7, 8], 'Logo'],
  ['D4-color.html', [1, 2, 3, 4], 'Color'],
  ['D5-typography.html', [1, 2, 4, 5], 'Typography'],
  ['D6-imagery.html', [2, 3, 4, 5, 7], 'Imagery and devices'],
  ['_book-chapters.html', ['open'], 'Open items'],
];

const read = (f) => fs.readFileSync(path.join(pages, f), 'utf8');
const between = (s, re) => [...s.matchAll(re)].map((m) => m[1]);

function scopeCss(css, scope) {
  css = css.replace(/\/\*[\s\S]*?\*\//g, '');
  return css.split('}').map((chunk) => {
    const i = chunk.indexOf('{');
    if (i < 0) return chunk;
    const sel = chunk.slice(0, i).trim();
    const body = chunk.slice(i);
    if (!sel || sel.startsWith('@')) return chunk;
    return sel.split(',').map((s) => `.${scope} ${s.trim()}`).join(', ') + ' ' + body;
  }).join('}\n');
}

const sources = [...new Set(PLAN.map((p) => p[0]))];
const heads = new Set();
let styles = '', body = '', scripts = '';
const keep = [];
for (const f of sources) {
  const html = read(f);
  const scope = 'bk-' + f.replace(/[^a-z0-9]/gi, '');
  for (const s of between(html, /<script src="([^"]+)"><\/script>/g)) heads.add(s);
  styles += between(html, /<style>([\s\S]*?)<\/style>/g).map((c) => scopeCss(c, scope)).join('\n');
  const sections = between(html, /(<section[\s\S]*?<\/section>)/g);
  sections.forEach((sec, i) => {
    const id = (sec.match(/data-book="([^"]+)"/) || [])[1];
    const key = `${f}#${id || i + 1}`;
    body += `<div class="${scope}" data-key="${key}">${sec}</div>\n`;
  });
  scripts += between(html, /<script>([\s\S]*?)<\/script>/g).map((s) => `(function(){ try {\n${s}\n} catch (e) { console.error('${f}', e); } })();`).join('\n');
}
const order = [];
const toc = [];
for (const [f, ids, title] of PLAN) {
  if (title) toc.push([title, order.length + 1]);
  for (const id of ids) order.push(`${f}#${id}`);
}

const out = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="nora-page" content="1600x1000">
<meta name="nora-output" content="D7">
<title>NORA Brand Guidelines</title>
<!-- GENERATED by scripts/build-book.mjs. Edit the source pages instead. -->
<link rel="stylesheet" href="_base.css">
${[...heads].map((s) => `<script src="${s}"></script>`).join('\n')}
<style>
${styles}
@media screen { body { background: #050505; } .bk-page { margin: 0 auto 24px; } }
</style>
</head>
<body>
${body}
<script>
${scripts}
(function () {
  const order = ${JSON.stringify(order)};
  const toc = ${JSON.stringify(toc)};
  const all = [...document.querySelectorAll('[data-key]')];
  const byKey = Object.fromEntries(all.map((el) => [el.dataset.key, el]));
  const frag = document.createDocumentFragment();
  order.forEach((k) => { if (byKey[k]) frag.appendChild(byKey[k]); else console.error('missing page', k); });
  all.forEach((el) => { if (!order.includes(el.dataset.key)) el.remove(); });
  document.body.insertBefore(frag, document.body.firstChild);
  // Renumber folios for the book.
  document.querySelectorAll('[data-key]').forEach((el, i) => {
    const f = el.querySelector('.folio');
    if (f) f.innerHTML = '<span>NORA · Brand guidelines</span><span>' + String(i + 1).padStart(2, '0') + '</span>';
  });
  const t = document.getElementById('toc');
  if (t) t.innerHTML = toc.map(([n, p]) => '<div><span>' + n + '</span><span>' + String(p).padStart(2, '0') + '</span></div>').join('');
})();
</script>
</body>
</html>
`;
fs.writeFileSync(path.join(pages, 'D7-guidelines.html'), out);
console.log(`book: ${order.length} pages -> src/pages/D7-guidelines.html`);
